export function findTemplateByKey(actionKey: string): DiyActionTemplate | null {
  return DIY_ACTION_TEMPLATES.find((t) => t.actionKey === actionKey) ?? null;
}

export function templatesForDimension(dimensionKey: string): DiyActionTemplate[] {
  return DIY_ACTION_TEMPLATES.filter((t) => t.dimensionKey === dimensionKey);
}
